#!/bin/sh
# Regenerates the "verbatim copy" driver functions (synthetic fixtures) from
# the read-only Gorodnichenko-Lee reference tree docs/src/code/goro_lee_r2/lib.
# Every line between a "BEGIN VERBATIM" and "END VERBATIM" marker is extracted
# with sed from the named file and line range; the only lines written by the
# driver are marked "% DRIVER".
# Usage (any cwd): sh test/fixtures/goro_lee/drivers/gen_verbatim_drivers.sh
set -e
HERE=$(cd "$(dirname "$0")" && pwd)
LIB="$HERE/../../../../docs/src/code/goro_lee_r2/lib"

verb() { # file first last
    printf '%% ---- BEGIN VERBATIM %s lines %s-%s ----\n' "$1" "$2" "$3"
    sed -n "$2,$3p" "$LIB/$1"
    printf '%% ---- END VERBATIM %s lines %s-%s ----\n' "$1" "$2" "$3"
}

# ---------------------------------------------------------------- R2
{
cat <<'H'
function out = sim_avar_r2_det(y, X, horizon, ylevel, trend, lagy, lagX)
% Deterministic prefix of SimulationAVarR2.m (lib/), seIndicator ~= 2.
% Copied verbatim: lines 107-121 (demeaning, SubR2 call, preAVar selection)
% and lines 183-190 (delta-method s.e.). The random bias correction
% (lines 123-174) is replaced by vdBc = vd, so the s.e. are evaluated at s-hat.
% Generated by gen_verbatim_drivers.sh -- do not edit by hand.
seIndicator = 1; % DRIVER: any value ~= 2 selects the pre-whitened GOGT, as the paper's seIndicator = 0 does (preAVar is unused here)
H
verb SimulationAVarR2.m 107 121
echo 'vdBc = vd; % DRIVER: replaces the random lines 123-174 (gradient at s-hat)'
echo 'details.vdSeAVarWPW  = zeros(horizon+1,1); % DRIVER: line 177 is one element short (Q19)'
echo 'details.vdSeAVarWoPW = zeros(horizon+1,1); % DRIVER'
verb SimulationAVarR2.m 183 190
cat <<'H'
out.vd = vd; % DRIVER: collect outputs
out.theta = details.preEstimates;
out.GOGTWPW = GOGTWPW;
out.GOGTWoPW = GOGTWoPW;
out.seWPW = details.vdSeAVarWPW;
out.seWoPW = details.vdSeAVarWoPW;
end
H
} > "$HERE/sim_avar_r2_det.m"

# ---------------------------------------------------------------- LP-A / LP-B
for M in A B; do
F=SimulationAVarLP$M.m
{
cat <<H
function out = sim_avar_lp${M}_det(y, X, horizon, ylevel, trend, lagy, lagX, XtIndicator, dfIndicator, XLP, lagyLP, lagXLP, XtIndicatorLP)
% Deterministic prefix of $F (lib/), jointIndicator = 0.
% Copied verbatim: line 156 (sample size), lines 194-214 (demeaning, SubLP$M
% call, Sigmaq, Nq), lines 216-261 (per-horizon theta, G, Z, GOGT with and
% without pre-whitening) and lines 313-328 (delta-method s.e.). The random
% lines 262-311 (PSD repair, mvnrnd draws, vdBc) are skipped and vdBc(h+1)
% is set to vd(h+1), so the gradient Deltah is evaluated at s-hat.
% Generated by gen_verbatim_drivers.sh -- do not edit by hand.
NBootstrap = 1;      % DRIVER: only sizes the unused vdb/NBootstrapIdx
jointIndicator = 0;  % DRIVER: horizon-by-horizon branch
H
verb $F 156 156
verb $F 194 214
verb $F 216 261
cat <<'H'
        % DRIVER: collect the deterministic per-horizon quantities
        out.theta{h+1,1} = thetah;
        out.G{h+1,1} = Gh;
        out.window(h+1,:) = [tminh, tmaxh, Th];
        out.Z{h+1,1} = Zh;
        vdBc(h+1) = vd(h+1); % DRIVER: replaces the random lines 262-311
H
verb $F 313 328
cat <<'H'
        out.Deltah{h+1,1} = Deltah; % DRIVER
    end % DRIVER: closes the for loop of line 223
end % DRIVER: closes the if of line 216
out.vd = vd; % DRIVER
out.ir = details.ir;
out.irSeAVar = details.irSeAVar;
out.varx = varx;
out.forecastErrorVar = forecastErrorVar;
out.Sigmaq = Sigmaq;
out.Nq = Nq;
out.t0LP = t0LP;
out.GOGTWPW = GOGTWPW;
out.GOGTWoPW = GOGTWoPW;
out.seWPW = details.vdSeAVarWPW;
out.seWoPW = details.vdSeAVarWoPW;
end
H
} > "$HERE/sim_avar_lp${M}_det.m"
done

# ---------------------------------------------------------------- IC block
{
cat <<'H'
function [IC, lagVAR, XVAR, T] = ic_block(y, X, ylevel, trend, lagVARSet, XVAROrder, yPlace, ICIndicator)
% Lag-selection block of BootstrapVARR2.m (lib/): line 104 (Ty, N) and
% lines 133-173 (XVAR construction and information criterion), verbatim.
% Generated by gen_verbatim_drivers.sh -- do not edit by hand.
IC = []; T = []; % DRIVER: stay empty when lagVARSet is a scalar
H
verb BootstrapVARR2.m 104 104
verb BootstrapVARR2.m 133 173
echo 'end'
} > "$HERE/ic_block.m"
